-- Phase23: rebuild the remaining 22 JP matchups as opponent-specific reviewed draft counters.
-- This migration never publishes or verifies matchup strategy. Device/lab-dependent interactions remain reviewed.

with ctx as (
  select
    (select id from characters where slug = 'jp') as jp_id,
    (select id from patches where is_current = true order by released_at desc limit 1) as patch_id
),
data(
  opponent_slug, opponent_name, suffix, counter_type, title, situation,
  summary, method, benefit, risk, difficulty, conditions,
  opponent_official_url, opponent_frame_url
) as (
  values
  ('aki','A.K.I.','approach','approach','JP vs A.K.I.：接近阻止','A.K.I.戦：接近手段を止める場面','毒弾（紫煙砲）・蛇軽功・凶襲突・DRを別経路として見る。毒付与後は接近の期待値が変わるため、無毒時と同じ迎撃を固定しない。','A.K.I.対面固有確認: 毒弾（紫煙砲）・蛇軽功・凶襲突・DRを別経路として見る。毒付与後は接近の期待値が変わるため、無毒時と同じ迎撃を固定しない。 相手固有の接近経路を最低4スロットに分け、JPの5MP・2MP・2HP・ガード・パリィ・後退を同じ画面位置から比較する。','A.K.I.戦で、中距離で一つの迎撃に固定せず、相手固有の接近経路ごとに回答を分けられる。','A.K.I.対面の注意: 移動技・派生・DRの成立距離は見た目だけで確定しない。未実機のDI相互作用や割り込みは候補のままにする。',4,'2026.08.03以降。画面位置と相手リソースを固定して反復する。 対象=A.K.I.。','https://www.streetfighter.com/6/buckler/ja-jp/battle_change/20260803/aki','https://ultimateframedata.com/sf6/aki'),
  ('aki','A.K.I.','punish','punish','JP vs A.K.I.：確反候補','A.K.I.戦：必殺技などをガードした後','紫煙追、蛇連咬、紫煙砲、凶襲突を版ごとにガードさせて反撃距離を確認する。verified例では紫煙追-16、弱/中/強蛇連咬-8/-12/-20。一方OD紫煙砲+1、OD凶襲突+2はガード後に自動暴れしない。','A.K.I.対面固有確認: 紫煙追、蛇連咬、紫煙砲、凶襲突を版ごとにガードさせて反撃距離を確認する。verified例では紫煙追-16、弱/中/強蛇連咬-8/-12/-20。一方OD紫煙砲+1、OD凶襲突+2はガード後に自動暴れしない。 current verified Frameを入口にし、JPの4F技・中距離反撃・SA候補が実際のガード後距離で届くか版ごとに確認する。','A.K.I.戦で、数値上のマイナスと実戦で届く確定反撃を分離し、誤確反を減らせる。','A.K.I.対面の注意: ガード差だけで確反を断定しない。距離・派生・強化状態・持続当てで結果が変わる技は個別確認する。',3,'現行verified Frameを使用。実距離で再現できた反撃だけを将来verified候補にする。 対象=A.K.I.。','https://www.streetfighter.com/6/buckler/ja-jp/battle_change/20260803/aki','https://ultimateframedata.com/sf6/aki'),
  ('aki','A.K.I.','air','anti_air','JP vs A.K.I.：対空・特殊軌道','A.K.I.戦：通常ジャンプと特殊軌道が混ざる場面','通常ジャンプと凶襲突・蛇軽功からの軌道変化を混ぜ、2HP・空中投げ・ガード・後退を比較する。','A.K.I.対面固有確認: 通常ジャンプと凶襲突・蛇軽功からの軌道変化を混ぜ、2HP・空中投げ・ガード・後退を比較する。 通常ジャンプと相手固有の空中/軌道変化をランダム再生し、2HP・空中投げ・ガード・後退の正答率と誤反応を記録する。','A.K.I.戦で、通常飛びを落とす力を維持しながら、特殊軌道への誤2HPや空振りを減らせる。','A.K.I.対面の注意: 特殊軌道を標準ジャンプと同じ発生・同じ当たり方として扱わない。高さや着地点は必ず記録する。',4,'20回以上のランダム再生。成功数だけでなく誤対空と空振り後被弾も記録する。 対象=A.K.I.。','https://www.streetfighter.com/6/buckler/ja-jp/battle_change/20260803/aki','https://ultimateframedata.com/sf6/aki'),
  ('aki','A.K.I.','corner','defense','JP vs A.K.I.：画面端防御','A.K.I.戦：JPが画面端を背負った場面','毒付与中の小技・投げ・蛇連咬・毒破裂狙いを録画し、ガード/Dリバ/パリィ/ジャンプ/ODアムネジアの結果を分ける。','A.K.I.対面固有確認: 毒付与中の小技・投げ・蛇連咬・毒破裂狙いを録画し、ガード/Dリバ/パリィ/ジャンプ/ODアムネジアの結果を分ける。 相手固有リソース有無を分け、打撃・投げ・遅らせ・代表固有択を録画し、ガード・Dリバ・パリィ・ジャンプ・ODアムネジアを比較する。','A.K.I.戦で、画面端で防御択を一つに固定せず、相手キャラの勝ち筋に応じて切り替えられる。','A.K.I.対面の注意: ODアムネジアの投げ成立後は2026.08.03変更後仕様で扱う。未確認セットプレイや1F割り込みを確定しない。',5,'端位置・Drive・SA・相手固有リソースを記録し、最低20局面を比較する。 対象=A.K.I.。','https://www.streetfighter.com/6/buckler/ja-jp/battle_change/20260803/aki','https://ultimateframedata.com/sf6/aki'),
  ('aki','A.K.I.','zoning','zoning','JP vs A.K.I.：弾・設置管理','A.K.I.戦：JPの遠距離択と相手固有行動が競合する場面','紫煙砲・紫泡泉/紫泡撒とJPのトルバラン/トリグラフ/ヴィーハトを同じ画面位置で比較し、毒弾を見てから設置を固定しない。','A.K.I.対面固有確認: 紫煙砲・紫泡泉/紫泡撒とJPのトルバラン/トリグラフ/ヴィーハトを同じ画面位置で比較し、毒弾を見てから設置を固定しない。 JPのトルバラン・トリグラフ・ヴィーハト・前歩きと相手固有の弾/設置/突進を同じ画面位置から比較し、成立・相打ち・ガード・不成立を記録する。','A.K.I.戦で、遠距離を『弾を撃つ場所』ではなく、画面位置と相互作用で選択するための対面表にできる。','A.K.I.対面の注意: 弾相殺・弾抜け・アーマー・反射などの具体相互作用はフレーム値だけで断定せず、実機再現後のみ確定する。',4,'遠・中遠・中距離の最低3位置で比較し、同じ条件を10回以上反復する。 対象=A.K.I.。','https://www.streetfighter.com/6/buckler/ja-jp/battle_change/20260803/aki','https://ultimateframedata.com/sf6/aki'),
  ('c-viper','C.ヴァイパー','approach','approach','JP vs C.ヴァイパー：接近阻止','C.ヴァイパー戦：接近手段を止める場面','セイスモ、バーニングキック、ハイジャンプキャンセル、DRを別々に再現し、JPの設置硬直を狙う経路と地上接近を区別する。','C.ヴァイパー対面固有確認: セイスモ、バーニングキック、ハイジャンプキャンセル、DRを別々に再現し、JPの設置硬直を狙う経路と地上接近を区別する。 相手固有の接近経路を最低4スロットに分け、JPの5MP・2MP・2HP・ガード・パリィ・後退を同じ画面位置から比較する。','C.ヴァイパー戦で、中距離で一つの迎撃に固定せず、相手固有の接近経路ごとに回答を分けられる。','C.ヴァイパー対面の注意: 移動技・派生・DRの成立距離は見た目だけで確定しない。未実機のDI相互作用や割り込みは候補のままにする。',4,'2026.08.03以降。画面位置と相手リソースを固定して反復する。 対象=C.ヴァイパー。','https://www.streetfighter.com/6/buckler/ja-jp/battle_change/20260803/cviper','https://ultimateframedata.com/sf6/cviper'),
  ('c-viper','C.ヴァイパー','punish','punish','JP vs C.ヴァイパー：確反候補','C.ヴァイパー戦：必殺技などをガードした後','サンダースラップ、トレースコンビネーション、セービングフォース、バーニングキックをガードし、距離別反撃を確認する。verified例では強サンダースラップ-24、弱/中は-4/-3、ODは-2、弱/中トレースは-15/-13。','C.ヴァイパー対面固有確認: サンダースラップ、トレースコンビネーション、セービングフォース、バーニングキックをガードし、距離別反撃を確認する。verified例では強サンダースラップ-24、弱/中は-4/-3、ODは-2、弱/中トレースは-15/-13。 current verified Frameを入口にし、JPの4F技・中距離反撃・SA候補が実際のガード後距離で届くか版ごとに確認する。','C.ヴァイパー戦で、数値上のマイナスと実戦で届く確定反撃を分離し、誤確反を減らせる。','C.ヴァイパー対面の注意: ガード差だけで確反を断定しない。距離・派生・強化状態・持続当てで結果が変わる技は個別確認する。',3,'現行verified Frameを使用。実距離で再現できた反撃だけを将来verified候補にする。 対象=C.ヴァイパー。','https://www.streetfighter.com/6/buckler/ja-jp/battle_change/20260803/cviper','https://ultimateframedata.com/sf6/cviper'),
  ('c-viper','C.ヴァイパー','air','anti_air','JP vs C.ヴァイパー：対空・特殊軌道','C.ヴァイパー戦：通常ジャンプと特殊軌道が混ざる場面','通常ジャンプ、ハイジャンプ系、バーニングキックの軌道を混ぜ、2HPだけに固定せず空中投げ・ガード・後退を比較する。','C.ヴァイパー対面固有確認: 通常ジャンプ、ハイジャンプ系、バーニングキックの軌道を混ぜ、2HPだけに固定せず空中投げ・ガード・後退を比較する。 通常ジャンプと相手固有の空中/軌道変化をランダム再生し、2HP・空中投げ・ガード・後退の正答率と誤反応を記録する。','C.ヴァイパー戦で、通常飛びを落とす力を維持しながら、特殊軌道への誤2HPや空振りを減らせる。','C.ヴァイパー対面の注意: 特殊軌道を標準ジャンプと同じ発生・同じ当たり方として扱わない。高さや着地点は必ず記録する。',4,'20回以上のランダム再生。成功数だけでなく誤対空と空振り後被弾も記録する。 対象=C.ヴァイパー。','https://www.streetfighter.com/6/buckler/ja-jp/battle_change/20260803/cviper','https://ultimateframedata.com/sf6/cviper'),
