upserted as (
  insert into counters (
    slug, defender_character_id, opponent_character_id, target_type, target_id,
    situation, counter_type, title, summary, method, benefit, risk, difficulty,
    conditions, valid_from_patch_id, valid_to_patch_id,
    verification_status, content_kind, status
  )
  select
    'jp-vs-' || d.opponent_slug || '-' || d.suffix,
    ctx.jp_id,
    o.id,
    'matchup',
    null,
    d.situation,
    d.counter_type,
    d.title,
    d.summary,
    d.method,
    d.benefit,
    d.risk,
    d.difficulty::smallint,
    d.conditions,
    ctx.patch_id,
    null,
    'reviewed',
    'strategy',
    'draft'
  from data d
  cross join ctx
  join characters o on o.slug = d.opponent_slug
  on conflict (slug) do update set
    defender_character_id = excluded.defender_character_id,
    opponent_character_id = excluded.opponent_character_id,
    target_type = excluded.target_type,
    target_id = null,
    situation = excluded.situation,
    counter_type = excluded.counter_type,
    title = excluded.title,
    summary = excluded.summary,
    method = excluded.method,
    benefit = excluded.benefit,
    risk = excluded.risk,
    difficulty = excluded.difficulty,
    conditions = excluded.conditions,
    valid_from_patch_id = excluded.valid_from_patch_id,
    valid_to_patch_id = null,
    verification_status = 'reviewed',
    content_kind = 'strategy',
    status = 'draft',
    updated_at = now()
  returning id, slug, opponent_character_id
)
select count(*) as rebuilt_detail_rows from upserted;

with ctx as (
  select
    (select id from characters where slug = 'jp') as jp_id,
    (select id from patches where is_current = true order by released_at desc limit 1) as patch_id
),
profiles(opponent_slug, opponent_name) as (
  values
  ('aki','A.K.I.'), ('c-viper','C.ヴァイパー'), ('alex','アレックス'), ('ingrid','イングリッド'), ('ed','エド'), ('e-honda','エドモンド本田'), ('elena','エレナ'), ('guile','ガイル'), ('kimberly','キンバリー'), ('sagat','サガット'), ('zangief','ザンギエフ'), ('jamie','ジェイミー'), ('dhalsim','ダルシム'), ('dee-jay','ディージェイ'), ('terry','テリー'), ('blanka','ブランカ'), ('manon','マノン'), ('marisa','マリーザ'), ('yasmine','ヤスミン'), ('ryu','リュウ'), ('lily','リリー'), ('chun-li','春麗')
)
insert into counters (
  slug, defender_character_id, opponent_character_id, target_type, target_id,
  situation, counter_type, title, summary, method, benefit, risk, difficulty,
  conditions, valid_from_patch_id, valid_to_patch_id,
  verification_status, content_kind, status
)
select
  'jp-matchup-' || p.opponent_slug,
  ctx.jp_id,
  o.id,
  'matchup_plan',
  null,
  '2026.08.03以降のJP対' || p.opponent_name,
  'matchup_overview',
  'JP vs ' || p.opponent_name || ' 対面対策',
  p.opponent_name || '対面を、接近阻止・確反候補・対空/特殊軌道・画面端防御・弾/設置の5項目へ分解した。',
  'jp-vs-' || p.opponent_slug || '-approach / punish / air / corner / zoning の5レコードをTrainingで再現し、確定・相打ち・読み・不成立を区別する。',
  p.opponent_name || '戦の対戦前確認からトレモ再検証までを一つの親対面として辿れる。',
  '距離、連携間隔、DI相互作用、弾相互作用、ODアムネジア後状況など実機依存項目はreviewedのまま扱う。',
  4,
  '2026.08.03以降。子Counter5件を参照。実機確認前はverified/publishedへ昇格しない。',
  ctx.patch_id,
  null,
  'reviewed',
  'strategy',
  'draft'
from profiles p
cross join ctx
join characters o on o.slug = p.opponent_slug
on conflict (slug) do update set
  defender_character_id = excluded.defender_character_id,
  opponent_character_id = excluded.opponent_character_id,
  target_type = excluded.target_type,
  target_id = null,
  situation = excluded.situation,
  counter_type = excluded.counter_type,
  title = excluded.title,
  summary = excluded.summary,
  method = excluded.method,
  benefit = excluded.benefit,
  risk = excluded.risk,
  difficulty = excluded.difficulty,
  conditions = excluded.conditions,
  valid_from_patch_id = excluded.valid_from_patch_id,
  valid_to_patch_id = null,
  verification_status = 'reviewed',
  content_kind = 'strategy',
  status = 'draft',
  updated_at = now();

-- Remove the obsolete import-audit-only link from the rebuilt parent indexes.
delete from entity_sources es
using counters co, sources s
where es.entity_type = 'counter'
  and es.entity_id = co.id
  and es.source_id = s.id
  and co.slug in ('jp-matchup-aki','jp-matchup-c-viper','jp-matchup-alex','jp-matchup-ingrid','jp-matchup-ed','jp-matchup-e-honda','jp-matchup-elena','jp-matchup-guile','jp-matchup-kimberly','jp-matchup-sagat','jp-matchup-zangief','jp-matchup-jamie','jp-matchup-dhalsim','jp-matchup-dee-jay','jp-matchup-terry','jp-matchup-blanka','jp-matchup-manon','jp-matchup-marisa','jp-matchup-yasmine','jp-matchup-ryu','jp-matchup-lily','jp-matchup-chun-li')
  and s.url = 'https://github.com/palzsoftware/SF6DNA/blob/sf6dna-v2/docs/PHASE13_JP_MATCHUP_COUNTER_IMPORT.md';

-- Attach four current evidence sources to all 22 parents and 110 detail rows.
with source_map(opponent_slug, opponent_official_url, opponent_frame_url) as (
  values
  ('aki','https://www.streetfighter.com/6/buckler/ja-jp/battle_change/20260803/aki','https://ultimateframedata.com/sf6/aki'), ('c-viper','https://www.streetfighter.com/6/buckler/ja-jp/battle_change/20260803/cviper','https://ultimateframedata.com/sf6/cviper'), ('alex','https://www.streetfighter.com/6/buckler/ja-jp/battle_change/20260803/alex','https://ultimateframedata.com/sf6/alex'), ('ingrid','https://www.streetfighter.com/6/buckler/ja-jp/battle_change/20260803/ingrid','https://ultimateframedata.com/sf6/ingrid'), ('ed','https://www.streetfighter.com/6/buckler/ja-jp/battle_change/20260803/ed','https://ultimateframedata.com/sf6/ed'), ('e-honda','https://www.streetfighter.com/6/buckler/ja-jp/battle_change/20260803/honda','https://ultimateframedata.com/sf6/ehonda'), ('elena','https://www.streetfighter.com/6/buckler/ja-jp/battle_change/20260803/elena','https://ultimateframedata.com/sf6/elena'), ('guile','https://www.streetfighter.com/6/buckler/ja-jp/battle_change/20260803/guile','https://ultimateframedata.com/sf6/guile'), ('kimberly','https://www.streetfighter.com/6/buckler/ja-jp/battle_change/20260803/kimberly','https://ultimateframedata.com/sf6/kimberly'), ('sagat','https://www.streetfighter.com/6/buckler/ja-jp/battle_change/20260803/sagat','https://ultimateframedata.com/sf6/sagat'), ('zangief','https://www.streetfighter.com/6/buckler/ja-jp/battle_change/20260803/zangief','https://ultimateframedata.com/sf6/zangief'), ('jamie','https://www.streetfighter.com/6/buckler/ja-jp/battle_change/20260803/jamie','https://ultimateframedata.com/sf6/jamie'), ('dhalsim','https://www.streetfighter.com/6/buckler/ja-jp/battle_change/20260803/dhalsim','https://ultimateframedata.com/sf6/dhalsim'), ('dee-jay','https://www.streetfighter.com/6/buckler/ja-jp/battle_change/20260803/deejay','https://ultimateframedata.com/sf6/deejay'), ('terry','https://www.streetfighter.com/6/buckler/ja-jp/battle_change/20260803/terry','https://ultimateframedata.com/sf6/terry'), ('blanka','https://www.streetfighter.com/6/buckler/ja-jp/battle_change/20260803/blanka','https://ultimateframedata.com/sf6/blanka'), ('manon','https://www.streetfighter.com/6/buckler/ja-jp/battle_change/20260803/manon','https://ultimateframedata.com/sf6/manon'), ('marisa','https://www.streetfighter.com/6/buckler/ja-jp/battle_change/20260803/marisa','https://ultimateframedata.com/sf6/marisa'), ('yasmine','https://www.streetfighter.com/6/buckler/ja-jp/battle_change/20260803/yasmine','https://ultimateframedata.com/sf6/yasmine'), ('ryu','https://www.streetfighter.com/6/buckler/ja-jp/battle_change/20260803/ryu','https://ultimateframedata.com/sf6/ryu'), ('lily','https://www.streetfighter.com/6/buckler/ja-jp/battle_change/20260803/lily','https://ultimateframedata.com/sf6/lily'), ('chun-li','https://www.streetfighter.com/6/buckler/ja-jp/battle_change/20260803/chunli','https://ultimateframedata.com/sf6/chunli')
),
target_rows as (
  select co.id, o.slug as opponent_slug
  from counters co
  join characters d on d.id = co.defender_character_id and d.slug = 'jp'
  join characters o on o.id = co.opponent_character_id
  where o.slug in (select opponent_slug from source_map)
    and (
      co.slug = 'jp-matchup-' || o.slug
      or co.slug like 'jp-vs-' || o.slug || '-%'
    )
    and co.status = 'draft'
    and co.verification_status = 'reviewed'
),
links as (
  select
    tr.id as entity_id,
    s.id as source_id,
    case
      when s.url = 'https://www.streetfighter.com/6/buckler/ja-jp/battle_change/20260803/jp' then 'patch_baseline'
      when s.url = 'https://ultimateframedata.com/sf6/jp' then 'corroborating'
      when s.url = sm.opponent_official_url then 'supporting'
      else 'corroborating'
    end as relationship
  from target_rows tr
  join source_map sm on sm.opponent_slug = tr.opponent_slug
  join sources s on s.url in (
    'https://www.streetfighter.com/6/buckler/ja-jp/battle_change/20260803/jp',
    'https://ultimateframedata.com/sf6/jp',
    sm.opponent_official_url,
    sm.opponent_frame_url
  )
)
insert into entity_sources (entity_type, entity_id, source_id, relationship, note)
select
  'counter',
  entity_id,
  source_id,
  relationship,
  '2026.08.03+ JP matchup rebuild; reviewed draft evidence.'
from links
on conflict (entity_type, entity_id, source_id) do update set
  relationship = excluded.relationship,
  note = excluded.note;
